struct P {
    long long x, y;
    P operator+(const P& o) const { return {x + o.x, y + o.y}; }
    P operator-(const P& o) const { return {x - o.x, y - o.y}; }
    P operator*(long long k) const { return {x * k, y * k}; }
    long long operator^(const P& o) const { return x * o.y - y * o.x; }   // iloczyn wektorowy
    bool operator==(const P& o) const { return x == o.x && y == o.y; }
    bool operator<(const P& o) const { return x != o.x ? x < o.x : y < o.y; }
    P& operator+=(const P& o) { x += o.x; y += o.y; return *this; }
};
ostream& operator<<(ostream& os, const P& p) { return os << '(' << p.x << ", " << p.y << ')'; }
istream& operator>>(istream& is, P& p) { return is >> p.x >> p.y; }

