    P a{1, 2}, b{3, -1};
    cout << a + b << ' ' << b - a << ' ' << a * 3 << '\n';   // (4, 1) (2, -3) (3, 6)
    cout << (a ^ b) << ' ' << (a == b) << ' ' << (a < b) << '\n';   // -7 0 1
