#include <bits/stdc++.h>
using namespace std;

template<class T>
T potega(T a, long long e, T mod) {            // szybkie potęgowanie dla dowolnego typu całkowitego
    T r = 1;
    a %= mod;
    while (e > 0) {
        if (e & 1) r = r * a % mod;
        a = a * a % mod;
        e >>= 1;
    }
    return r;
}

template<class T>
struct Fenwick {                               // drzewo Fenwicka z typem wartości T
    int n;
    vector<T> t;
    Fenwick(int n_) : n(n_), t(n_ + 1, 0) {}
    void add(int i, T v) { for (; i <= n; i += i & -i) t[i] += v; }
    T sum(int i) const { T s = 0; for (; i > 0; i -= i & -i) s += t[i]; return s; }
};

template<class T>
void wypisz(const vector<T>& v) {
    for (const auto& x : v) cout << x << ' ';
    cout << '\n';
}

int main() {
    cout << potega<long long>(2, 30, 1000000007) << '\n';   // 73741817
    Fenwick<long long> f(10);
    f.add(3, 5); f.add(7, 10);
    cout << f.sum(5) << ' ' << f.sum(10) << '\n';           // 5 15
    wypisz(vector<int>{1, 2, 3});
    wypisz(vector<string>{"a", "b"});
}

template<int N>
struct Macierz {                         // parametr szablonu będący liczbą
    long long a[N][N] = {};
    Macierz operator*(const Macierz& o) const {
        Macierz r;
        for (int i = 0; i < N; i++)
            for (int k = 0; k < N; k++)
                for (int j = 0; j < N; j++) r.a[i][j] += a[i][k] * o.a[k][j];
        return r;
    }
};
